-- ----------------------------------------------------------------
-- 按 item_template 61001「[幻]霜之哀伤」批量生成新物品
-- entry 64000 ~ 64129  <->  displayid 500000 ~ 500129
-- 武器 109 个 + 护甲 21 个；可重复执行，只写非默认值列
-- ----------------------------------------------------------------

DELETE FROM `item_template` WHERE `entry` BETWEEN 64000 AND 64129;

-- 武器：class=2，subclass / InventoryType / sheath / Material 按模型类型
;

-- 护甲：class=4（板甲），无伤害，armor 占位
;
